LINES.forEach(L=>{if(L.c===5)L.boss=true});
const poolIdx=l=>LINES[l].from!=null?LINES[l].from:l;
const typesOf=(L,star)=>Array.isArray(L.t[0])?L.t[Math.min(star,L.t.length)-1]:L.t;
const isSpec=L=>L.role==='mage'||L.role==='support';
function baseStats(L,star,towerPlayer=true){
  const R=ROLES[L.role],c=L.c-1,sm=L.sm[star-1];
  const stats={speciesId:L.ids[star-1],shedinja:window.OAK_IDLE_MODE&&L.ids[star-1]===292,hp:HPB[c]*R.hp*Math.pow(1.8,star-1)*sm,atk:ATKB[c]*R.atk*Math.pow(1.5,star-1)*sm,
   sp:SPB[c]*Math.pow(1.55,star-1)*(isSpec(L)?1.15:1)*Math.sqrt(sm),as:R.as,armor:R.ar+c*4,mr:R.mr+c*4,
   range:R.rg,maxMana:R.mana+(L.mv.p>=1.7?20:0),mana0:R.m0};
  if(stats.shedinja)stats.hp=1;return towerPlayer&&window.TOWER?TOWER.legendaryStats(L,stats):stats;
}

